// Page-by-page question bank, written from Promita's printed Scrum Guide pages.
// Add a new set to PAGE_SETS for each batch of pages.
//
// Question types:
//   single - one correct answer.            a: [correct], w: [wrong options]
//   tf     - true or false.                 a: ["True"] or ["False"]
//   blank  - fill in the missing word.      q uses ____ ; a: [correct], w: [wrong]
//   multi  - choose all that apply / two.   a: [all correct], w: [wrong]
//   order  - put the steps in order.        items: [steps in the correct order]
// Add sc:1 to mark a workplace scenario question (shown under the Scenarios filter).
// Every question has a topic and a "why" explanation.
window.PAGE_SETS = [
{
  id: "p3-4",
  title: "Pages 3–4",
  sub: "Scrum definition, theory, the three pillars and the five values",
  qs: [
  // ---- Scrum definition
  {type:"single",topic:"Definition",q:"How does the Scrum Guide define Scrum?",a:["A lightweight framework that helps people, teams and organizations generate value through adaptive solutions for complex problems"],w:["A project management methodology for delivering fixed scope on time","A set of detailed instructions for software development teams","A process for planning simple, predictable work"],why:"Scrum is a lightweight framework. It is not a methodology or a detailed process, and it targets complex problems."},
  {type:"blank",topic:"Definition",q:"Scrum is a ____ framework that helps people, teams and organizations generate value.",a:["lightweight"],w:["complete","prescriptive","heavyweight"],why:"The guide calls Scrum a lightweight framework."},
  {type:"blank",topic:"Definition",q:"Scrum helps people, teams and organizations ____ value through adaptive solutions for complex problems.",a:["generate"],w:["measure","forecast","protect"],why:"The definition: Scrum helps people, teams and organizations generate value through adaptive solutions for complex problems."},
  {type:"single",topic:"Definition",q:"What kind of problems is Scrum designed for?",a:["Complex problems"],w:["Simple, repeatable problems","Only software problems","Problems with fully known requirements"],why:"Scrum delivers adaptive solutions for complex problems, where more is unknown than known."},
  {type:"multi",topic:"Definition",q:"Scrum helps which of these generate value? (Choose three.)",a:["People","Teams","Organizations"],w:["Only software developers","Only project managers"],why:"The definition names people, teams and organizations. Scrum is not limited to software or to one role."},
  {type:"single",topic:"Definition",q:"Scrum creates value through what kind of solutions?",a:["Adaptive solutions"],w:["Predictive solutions","Standardized solutions","Fixed-scope solutions"],why:"Scrum generates value through adaptive solutions, adjusting as the team learns."},
  {type:"tf",topic:"Definition",q:"True or false: Scrum is a methodology that tells teams exactly how to do their work.",a:["False"],why:"Scrum is a lightweight framework. Rather than detailed instructions, its rules guide people's relationships and interactions."},

  // ---- In a nutshell
  {type:"single",topic:"In a nutshell",q:"In a nutshell, Scrum requires whom to foster an environment where the Scrum cycle can happen?",a:["The Scrum Master"],w:["The Product Owner","The Developers","Senior management"],why:"In a nutshell, Scrum requires a Scrum Master to foster an environment where the four steps happen."},
  {type:"order",topic:"In a nutshell",q:"Put the four \"Scrum in a nutshell\" steps in order.",items:["A Product Owner orders the work for a complex problem into a Product Backlog","The Scrum Team turns a selection of the work into an Increment of value during a Sprint","The Scrum Team and its stakeholders inspect the results and adjust for the next Sprint","Repeat"],why:"Order the work, build an Increment in a Sprint, inspect and adjust, then repeat."},
  {type:"single",topic:"In a nutshell",q:"Who orders the work for a complex problem into a Product Backlog?",a:["The Product Owner"],w:["The Scrum Master","The Developers","The stakeholders"],why:"The Product Owner orders the work into the Product Backlog."},
  {type:"blank",topic:"In a nutshell",q:"A Product Owner ____ the work for a complex problem into a Product Backlog.",a:["orders"],w:["assigns","estimates","approves"],why:"The PO orders (not assigns or estimates) the work. Ordering is a key PO responsibility."},
  {type:"single",topic:"In a nutshell",q:"In the nutshell description, who turns a selection of the work into an Increment of value during a Sprint?",a:["The Scrum Team"],w:["The Product Owner alone","The Scrum Master","The stakeholders"],why:"The nutshell says the Scrum Team turns a selection of the work into an Increment of value during a Sprint."},
  {type:"single",topic:"In a nutshell",q:"During a Sprint, a selection of the work is turned into:",a:["An Increment of value"],w:["A release plan","A Product Backlog","A status report"],why:"The Scrum Team turns a selection of the work into an Increment of value during a Sprint."},
  {type:"multi",topic:"In a nutshell",q:"Who inspects the results and adjusts for the next Sprint? (Choose two.)",a:["The Scrum Team","Its stakeholders"],w:["A project manager","An external auditor"],why:"The Scrum Team and its stakeholders inspect the results and adjust for the next Sprint."},
  {type:"blank",topic:"In a nutshell",q:"The Scrum Team and its stakeholders inspect the results and ____ for the next Sprint.",a:["adjust"],w:["report","celebrate","sign off"],why:"Inspect and adjust: this is empiricism in action."},

  // ---- Scrum is simple / incomplete
  {type:"single",topic:"Definition",q:"What does the Scrum Guide recommend when starting with Scrum?",a:["Try it as is and determine if its philosophy, theory and structure help to achieve goals and create value"],w:["Change the parts that don't fit your company before trying it","Adopt only the events you like","Run it for a year before judging it"],why:"Scrum is simple. Try it as is and determine if it helps achieve goals and create value."},
  {type:"tf",topic:"Definition",q:"True or false: The Scrum framework is purposefully incomplete.",a:["True"],why:"It is purposefully incomplete, defining only the parts required to implement Scrum theory."},
  {type:"single",topic:"Definition",q:"Why is Scrum purposefully incomplete?",a:["It only defines the parts required to implement Scrum theory"],w:["The Scrum Guide is still being written","Each company must write its own Scrum Guide","The Scrum Master fills in the missing rules"],why:"Scrum defines only what's needed to implement its theory. The rest comes from the collective intelligence of the people using it."},
  {type:"single",topic:"Definition",q:"Scrum is built upon:",a:["The collective intelligence of the people using it"],w:["The Scrum Master's expertise","Management's instructions","Industry best practices"],why:"Scrum is built upon by the collective intelligence of the people using it."},
  {type:"single",topic:"Definition",q:"Rather than providing detailed instructions, what does Scrum do?",a:["Its rules guide people's relationships and interactions"],w:["It provides templates for every task","It assigns tasks to individuals","It lets the Scrum Master make all decisions"],why:"Rather than detailed instructions, the rules of Scrum guide relationships and interactions."},
  {type:"tf",topic:"Definition",q:"True or false: Various processes, techniques and methods can be used within the Scrum framework.",a:["True"],why:"Various processes, techniques and methods can be employed within the framework."},
  {type:"blank",topic:"Definition",q:"Scrum wraps around existing practices or ____ them unnecessary.",a:["renders"],w:["documents","standardizes","approves"],why:"Scrum wraps around existing practices or renders them unnecessary."},
  {type:"multi",topic:"Definition",q:"Scrum makes visible the relative efficacy of which of these? (Choose three.)",a:["Current management","Environment","Work techniques"],w:["Individual salaries","Team velocity"],why:"Scrum makes visible the relative efficacy of current management, environment and work techniques."},
  {type:"single",topic:"Definition",q:"Why does Scrum make visible the efficacy of current management, environment and work techniques?",a:["So that improvements can be made"],w:["So management can rate individuals","To compare teams with each other","To set performance targets"],why:"Making things visible lets improvements be made. It is not for judging people."},
  {sc:1,type:"single",topic:"Definition",q:"A new team wants to replace parts of Scrum with their company's existing process before they start. What does the Scrum Guide suggest?",a:["Try Scrum as is first, then judge whether it helps them achieve goals and create value"],w:["Change Scrum first so it fits the company","Ask management which parts to keep","Skip the events that seem unnecessary"],why:"The guide says: try it as is. Scrum can wrap around existing practices, but its parts should be used as defined."},

  // ---- Scrum theory
  {type:"multi",topic:"Theory",q:"Scrum is founded on which two ideas? (Choose two.)",a:["Empiricism","Lean thinking"],w:["Predictive planning","Command and control","Waterfall phases"],why:"Scrum is founded on empiricism and lean thinking."},
  {type:"blank",topic:"Theory",q:"Empiricism asserts that knowledge comes from ____ and making decisions based on what is observed.",a:["experience"],w:["planning","expert opinion","documentation"],why:"Empiricism: knowledge comes from experience and making decisions based on what is observed."},
  {type:"single",topic:"Theory",q:"According to empiricism, decisions should be based on:",a:["What is observed"],w:["What was planned at the start","What managers expect","What worked for other teams"],why:"Empiricism means deciding based on what is observed, not on predictions."},
  {type:"single",topic:"Theory",q:"What does lean thinking do?",a:["Reduces waste and focuses on the essentials"],w:["Maximizes how busy each person is","Adds detailed documentation","Plans everything upfront"],why:"Lean thinking reduces waste and focuses on the essentials."},
  {type:"single",topic:"Theory",q:"Which statement describes empiricism, not lean thinking?",a:["Knowledge comes from experience and observation"],w:["Reduce waste","Focus on the essentials","Remove unnecessary work"],why:"Empiricism is about learning from experience and observation. Reducing waste and focusing on essentials is lean thinking."},
  {type:"single",topic:"Theory",q:"What approach does Scrum employ?",a:["An iterative, incremental approach"],w:["A sequential, phase-by-phase approach","A big-bang delivery approach","An ad hoc approach"],why:"Scrum employs an iterative, incremental approach."},
  {type:"multi",topic:"Theory",q:"Scrum's iterative, incremental approach is used to: (Choose two.)",a:["Optimize predictability","Control risk"],w:["Maximize resource utilization","Guarantee a fixed delivery date","Reduce the need for stakeholders"],why:"Scrum uses an iterative, incremental approach to optimize predictability and control risk."},
  {type:"single",topic:"Theory",q:"Scrum engages groups of people who:",a:["Collectively have all the skills and expertise to do the work, and share or acquire skills as needed"],w:["Each specialize in only one skill","Depend on outside experts for most work","Are each assigned work by a team lead"],why:"The group collectively has the skills, and members share or acquire skills as needed."},
  {type:"tf",topic:"Theory",q:"True or false: Every individual on a Scrum Team must have all the skills needed to do the work.",a:["False"],why:"The group collectively has all the skills. Individuals don't each need every skill, and they share or acquire skills as needed."},
  {type:"single",topic:"Theory",q:"How many formal events for inspection and adaptation does Scrum combine within the Sprint?",a:["Four"],w:["Three","Five","Six"],why:"Scrum combines four formal events within a containing event, the Sprint. That makes five events in total."},
  {type:"single",topic:"Theory",q:"What is the containing event for Scrum's four formal events?",a:["The Sprint"],w:["The Sprint Review","The release","The Daily Scrum"],why:"The Sprint contains Sprint Planning, the Daily Scrum, the Sprint Review and the Sprint Retrospective."},
  {type:"tf",topic:"Theory",q:"True or false: The Sprint is one of the four formal events held inside the Sprint.",a:["False"],why:"The Sprint is the container. The four formal events inside it are Sprint Planning, Daily Scrum, Sprint Review and Sprint Retrospective. Five events in total."},
  {type:"single",topic:"Theory",q:"Why do the Scrum events work?",a:["They implement the empirical pillars of transparency, inspection and adaptation"],w:["They are timeboxed by management","The Scrum Master runs them","They produce detailed reports"],why:"The events work because they implement the empirical Scrum pillars."},

  // ---- Pillars: transparency
  {type:"single",topic:"Pillars",q:"What are the three empirical Scrum pillars?",a:["Transparency, inspection and adaptation"],w:["Commitment, focus and courage","Planning, execution and review","Openness, respect and transparency"],why:"The three pillars are transparency, inspection and adaptation."},
  {type:"order",topic:"Pillars",q:"Put the pillars in the order each one enables the next.",items:["Transparency","Inspection","Adaptation"],why:"Transparency enables inspection, and inspection enables adaptation."},
  {type:"single",topic:"Pillars",q:"Transparency: the emergent process and work must be visible to whom?",a:["Those performing the work and those receiving the work"],w:["Only the Scrum Team","Only the stakeholders","Only management"],why:"The work must be visible to those performing it as well as those receiving it."},
  {type:"single",topic:"Pillars",q:"With Scrum, important decisions are based on:",a:["The perceived state of its three formal artifacts"],w:["The Scrum Master's judgment","The team's velocity","Weekly status reports"],why:"Important decisions are based on the perceived state of the three formal artifacts."},
  {type:"single",topic:"Pillars",q:"How many formal artifacts does Scrum have?",a:["Three"],w:["Two","Four","Five"],why:"The three artifacts are the Product Backlog, the Sprint Backlog and the Increment."},
  {type:"multi",topic:"Pillars",q:"Artifacts with low transparency can lead to decisions that: (Choose two.)",a:["Diminish value","Increase risk"],w:["Improve predictability","Reduce waste"],why:"Low transparency can lead to decisions that diminish value and increase risk."},
  {type:"blank",topic:"Pillars",q:"Transparency enables ____.",a:["inspection"],w:["adaptation","planning","commitment"],why:"Transparency enables inspection."},
  {type:"single",topic:"Pillars",q:"Inspection without transparency is:",a:["Misleading and wasteful"],w:["Pointless","Acceptable in short Sprints","Required before adaptation"],why:"Inspection without transparency is misleading and wasteful. (Inspection without adaptation is pointless.)"},

  // ---- Pillars: inspection
  {type:"single",topic:"Pillars",q:"What must be inspected frequently and diligently?",a:["The Scrum artifacts and progress toward agreed goals"],w:["Each person's individual performance","Only the finished product at release","The team's working hours"],why:"The artifacts and progress toward agreed goals must be inspected frequently and diligently."},
  {type:"single",topic:"Pillars",q:"What is the purpose of inspection?",a:["To detect potentially undesirable variances or problems"],w:["To find someone to blame","To approve each Developer's work","To report status to management"],why:"Inspection detects potentially undesirable variances or problems."},
  {type:"single",topic:"Pillars",q:"To help with inspection, Scrum provides cadence in the form of:",a:["Its five events"],w:["Weekly status meetings","Its three artifacts","Monthly audits"],why:"Scrum provides cadence for inspection through its five events."},
  {type:"blank",topic:"Pillars",q:"Inspection enables ____.",a:["adaptation"],w:["transparency","commitment","estimation"],why:"Inspection enables adaptation."},
  {type:"single",topic:"Pillars",q:"Inspection without adaptation is considered:",a:["Pointless"],w:["Misleading and wasteful","Acceptable","The Product Owner's responsibility"],why:"Inspection without adaptation is pointless. Watch out: inspection without transparency is misleading and wasteful."},
  {type:"single",topic:"Pillars",q:"Complete both: inspection without transparency is ____; inspection without adaptation is ____.",a:["Misleading and wasteful; pointless"],w:["Pointless; misleading and wasteful","Risky; slow","Wasteful; acceptable"],why:"A common trap. Without transparency, inspection misleads. Without adaptation, inspection is pointless."},
  {type:"single",topic:"Pillars",q:"Scrum events are designed to:",a:["Provoke change"],w:["Report status","Control the team","Approve work"],why:"Scrum events are designed to provoke change."},

  // ---- Pillars: adaptation
  {type:"single",topic:"Pillars",q:"When must the process or the materials being produced be adjusted?",a:["When any aspect deviates outside acceptable limits or the resulting product is unacceptable"],w:["Only at the end of a release","Only when management requests it","Only during the Sprint Retrospective"],why:"Adjust when a process deviates outside acceptable limits or the resulting product is unacceptable."},
  {type:"multi",topic:"Pillars",q:"If a process deviates outside acceptable limits, what must be adjusted? (Choose two.)",a:["The process being applied","The materials being produced"],w:["The team's members","The Scrum Guide"],why:"The process being applied or the materials being produced must be adjusted."},
  {type:"single",topic:"Pillars",q:"When must an adjustment be made?",a:["As soon as possible, to minimize further deviation"],w:["At the next Sprint Retrospective","At the end of the Sprint","After management approves"],why:"The adjustment must be made as soon as possible to minimize further deviation."},
  {type:"single",topic:"Pillars",q:"Adaptation becomes more difficult when:",a:["The people involved are not empowered or self-managing"],w:["Sprints are shorter than one month","The team has fewer than 10 people","The Product Backlog is ordered"],why:"Adaptation becomes more difficult when people are not empowered or self-managing."},
  {type:"single",topic:"Pillars",q:"When is a Scrum Team expected to adapt?",a:["The moment it learns anything new through inspection"],w:["Only at the Sprint Retrospective","At the end of each Sprint","When the Product Owner approves"],why:"A Scrum Team is expected to adapt the moment it learns anything new through inspection."},
  {sc:1,type:"single",topic:"Pillars",q:"Mid-Sprint, the Developers find their current approach is producing unacceptable quality. What should they do?",a:["Adjust their approach as soon as possible"],w:["Wait for the Sprint Retrospective to discuss it","Finish the Sprint and fix it in the next one","Ask management for permission to change"],why:"Adjust as soon as possible to minimize further deviation. The team adapts the moment it learns something new."},

  // ---- Values
  {type:"multi",topic:"Values",q:"Which are the five Scrum values? (Choose all that apply.)",a:["Commitment","Focus","Openness","Respect","Courage"],w:["Transparency","Simplicity"],why:"The values are commitment, focus, openness, respect and courage. Transparency is a pillar, not a value."},
  {type:"single",topic:"Values",q:"How many Scrum values are there?",a:["Five"],w:["Three","Four","Six"],why:"There are five values: commitment, focus, openness, respect and courage."},
  {type:"tf",topic:"Values",q:"True or false: Transparency is one of the five Scrum values.",a:["False"],why:"Transparency is one of the three pillars. The values are commitment, focus, openness, respect and courage."},
  {type:"single",topic:"Values",q:"Successful use of Scrum depends on people becoming more proficient in:",a:["Living the five values"],w:["Writing user stories","Estimating with story points","Following the Scrum Master's instructions"],why:"Successful use of Scrum depends on people becoming more proficient in living five values."},
  {type:"single",topic:"Values",q:"\"The Scrum Team commits to achieving its goals and to supporting each other.\" Which value is this?",a:["Commitment"],w:["Focus","Respect","Courage"],why:"Commitment: achieving its goals and supporting each other."},
  {type:"single",topic:"Values",q:"\"Their primary focus is on the work of the Sprint to make the best possible progress toward these goals.\" Which value is this?",a:["Focus"],w:["Commitment","Openness","Courage"],why:"Focus is on the work of the Sprint and progress toward the goals."},
  {type:"single",topic:"Values",q:"Under the value of openness, who is open about the work and the challenges?",a:["The Scrum Team and its stakeholders"],w:["Only the Scrum Master","Only the Product Owner","Only the Developers"],why:"The Scrum Team and its stakeholders are open about the work and the challenges."},
  {type:"single",topic:"Values",q:"\"Members see each other as capable, independent people, and are seen that way by the people they work with.\" Which value is this?",a:["Respect"],w:["Openness","Commitment","Focus"],why:"Respect: team members respect each other to be capable, independent people, and are respected as such."},
  {type:"single",topic:"Values",q:"Courage means Scrum Team members have the courage to:",a:["Do the right thing and work on tough problems"],w:["Overrule the Product Owner","Skip events when busy","Commit to fixed scope"],why:"The Scrum Team members have the courage to do the right thing, to work on tough problems."},
  {sc:1,type:"single",topic:"Values",q:"A Developer is afraid to tell the Product Owner that the Sprint Goal is at risk. Which value most needs strengthening?",a:["Courage"],w:["Focus","Commitment","Respect"],why:"Raising hard news takes courage, doing the right thing even when it's uncomfortable."},
  {sc:1,type:"single",topic:"Values",q:"The team hides failing tests from stakeholders at the Sprint Review. Which value is missing?",a:["Openness"],w:["Focus","Commitment","Respect"],why:"Openness: the Scrum Team and stakeholders are open about the work and its challenges. Hiding problems also hurts transparency."},
  {sc:1,type:"single",topic:"Values",q:"A Developer keeps getting pulled into unrelated work and can't make progress toward the Sprint Goal. Which value is affected most?",a:["Focus"],w:["Openness","Courage","Respect"],why:"Focus is on the work of the Sprint to make the best possible progress toward its goals."},
  {type:"single",topic:"Values",q:"The values give the Scrum Team direction with regard to their:",a:["Work, actions and behavior"],w:["Salaries and titles","Tools and technology","Contracts and budgets"],why:"These values give direction to the Scrum Team with regard to their work, actions and behavior."},
  {type:"single",topic:"Values",q:"Decisions made, steps taken and the way Scrum is used should:",a:["Reinforce the values, not diminish or undermine them"],w:["Follow management's priorities first","Be approved by the Scrum Master","Maximize team velocity"],why:"Decisions and the way Scrum is used should reinforce these values, not diminish or undermine them."},
  {type:"single",topic:"Values",q:"How do Scrum Team members learn the values?",a:["They learn and explore them as they work with the Scrum events and artifacts"],w:["Through mandatory HR training","The Scrum Master teaches them before the first Sprint","By reading the Scrum Guide once"],why:"Team members learn and explore the values as they work with the Scrum events and artifacts."},
  {type:"single",topic:"Values",q:"When the values are embodied by the Scrum Team and the people they work with, what comes to life?",a:["The empirical pillars of transparency, inspection and adaptation"],w:["The Definition of Done","Team velocity","The release plan"],why:"When the values are embodied, the empirical pillars come to life, building trust."},
  {type:"blank",topic:"Values",q:"When the values are embodied, the empirical pillars come to life, building ____.",a:["trust"],w:["velocity","predictability","commitment"],why:"Living the values brings the pillars to life and builds trust."},
  {type:"single",topic:"Values",q:"Which of these is a Scrum pillar rather than a Scrum value?",a:["Inspection"],w:["Openness","Courage","Focus"],why:"Inspection is a pillar. Openness, courage and focus are values. Don't mix up the 3 pillars and the 5 values."},
  // ---- Scenarios (real-workplace situations)
  {sc:1,type:"single",topic:"Definition",q:"A manager asks the Scrum Master for a detailed instruction manual telling each person exactly how to do their job in Scrum. What's the best response?",a:["Scrum doesn't give detailed instructions; its rules guide relationships and interactions, and the team decides how to work"],w:["Write the manual, since every role needs step-by-step instructions","Ask the Product Owner to write it","Buy a Scrum process template that covers every task"],why:"Rather than detailed instructions, the rules of Scrum guide relationships and interactions. Scrum is built upon by the collective intelligence of the people using it."},
  {sc:1,type:"single",topic:"Definition",q:"A team moving to Scrum already uses a task board and peer code reviews. They ask if they must stop using them. What should they be told?",a:["No. Various processes, techniques and methods can be used within the Scrum framework"],w:["Yes. Only practices named in the Scrum Guide are allowed","Yes, until the team has finished three Sprints","Only if the Scrum Master approves each practice"],why:"Scrum wraps around existing practices or renders them unnecessary. Complementary practices are fine inside the framework."},
  {sc:1,type:"single",topic:"Definition",q:"A few Sprints in, it becomes obvious that a slow company approval process delays every release. What is Scrum doing here?",a:["Making visible the efficacy of current management, environment and work techniques, so improvements can be made"],w:["Failing, because Scrum should remove all delays automatically","Creating a new problem that didn't exist before","Showing the team needs a project manager"],why:"Scrum makes visible how well current management, environment and techniques work, so improvements can be made. The problem existed already; Scrum exposed it."},
  {sc:1,type:"single",topic:"Definition",q:"A director says Scrum is \"too simple\" because it doesn't say how to estimate or report status. How does the Scrum Guide explain this?",a:["Scrum is purposefully incomplete; it defines only what's needed to implement Scrum theory, and teams add practices within it"],w:["The director is right, so the team should drop Scrum","The Scrum Master must invent the missing rules","The Product Owner must define estimation and reporting rules for all teams"],why:"The framework is purposefully incomplete. The gaps are filled by the collective intelligence of the people using it."},
  {sc:1,type:"single",topic:"In a nutshell",q:"A senior stakeholder keeps telling the Developers directly which features to build next. According to Scrum, who orders the work in the Product Backlog?",a:["The Product Owner"],w:["The most senior stakeholder","The Developers, by vote","The Scrum Master"],why:"A Product Owner orders the work for a complex problem into a Product Backlog. Stakeholders who want changes work through the PO."},
  {sc:1,type:"single",topic:"In a nutshell",q:"To save time, a team starts holding Sprint Reviews without any stakeholders. What part of the Scrum cycle is weakened?",a:["The Scrum Team and its stakeholders inspecting the results and adjusting for the next Sprint"],w:["The Product Owner ordering the Product Backlog","The Developers creating the Increment","Nothing, stakeholders are optional in Scrum"],why:"In a nutshell, the Scrum Team and its stakeholders inspect the results and adjust. Leaving stakeholders out weakens inspection and adaptation."},
  {sc:1,type:"single",topic:"Theory",q:"The Product Owner tells stakeholders a 12-month feature plan is fixed and won't change, whatever is learned. Which part of Scrum theory does this conflict with most?",a:["Empiricism: decisions should be based on what is observed"],w:["Lean thinking: reduce waste","The Scrum value of focus","Self-management"],why:"Empiricism says knowledge comes from experience and decisions are based on what is observed. Locking a plan ignores what the team will learn."},
  {sc:1,type:"single",topic:"Theory",q:"A team spends hours each Sprint writing detailed reports that nobody reads. Which idea Scrum is founded on would challenge this?",a:["Lean thinking: reduce waste and focus on the essentials"],w:["Empiricism: learn from experience","The Scrum value of courage","The pillar of transparency"],why:"Lean thinking reduces waste and focuses on the essentials. Unread reports are waste."},
  {sc:1,type:"single",topic:"Theory",q:"Only one Developer knows the database. When she's away, related work stops. What does Scrum theory suggest?",a:["The team collectively needs the skills, so members should share or acquire them as needed"],w:["Hire a database specialist outside the team","Plan Sprints around her vacation","Remove database work from the Product Backlog"],why:"Scrum engages groups who collectively have the skills to do the work and share or acquire skills as needed."},
  {sc:1,type:"single",topic:"Theory",q:"A company wants to build the whole product over 18 months and deliver it all at the end. What does Scrum do differently, and why?",a:["Uses an iterative, incremental approach to optimize predictability and control risk"],w:["Delivers everything at once to reduce rework","Plans every detail upfront to remove uncertainty","Adds more people to finish sooner"],why:"Scrum employs an iterative, incremental approach to optimize predictability and control risk, delivering Increments every Sprint."},
  {sc:1,type:"single",topic:"Theory",q:"Leadership wants to cancel Sprint Retrospectives to save time. What is the main problem?",a:["The events implement inspection and adaptation; removing one weakens empiricism"],w:["There's no problem, the Retrospective is optional","Only the Scrum Master would lose information","It would shorten the Sprint by three hours"],why:"Scrum's four events inside the Sprint work because they implement the pillars of transparency, inspection and adaptation."},
  {sc:1,type:"single",topic:"Pillars",q:"Stakeholders can't see how the Sprint is going because the board is updated only once a week. Which pillar is weakest?",a:["Transparency"],w:["Inspection","Adaptation","Focus"],why:"The emergent process and work must be visible to those doing the work and those receiving it. That's transparency."},
  {sc:1,type:"single",topic:"Pillars",q:"A team inspects a Product Backlog that's out of date and unclear, then makes release decisions from it. What's the risk?",a:["The inspection is misleading and wasteful, and decisions may diminish value and increase risk"],w:["No risk, any inspection is better than none","Only the Developers are affected","The Sprint Goal automatically changes"],why:"Inspection without transparency is misleading and wasteful. Low-transparency artifacts lead to decisions that diminish value and increase risk."},
  {sc:1,type:"single",topic:"Pillars",q:"At every Sprint Review, stakeholders give feedback, everyone agrees, but nothing in the Product Backlog ever changes. What's wrong?",a:["Inspection without adaptation is pointless"],w:["Inspection without transparency is misleading","The Sprint Review is too short","The stakeholders aren't committed"],why:"Inspection enables adaptation. If nothing changes after inspecting, the inspection was pointless."},
  {sc:1,type:"single",topic:"Pillars",q:"A team checks progress only at the end of a six-month release. What does Scrum say?",a:["Artifacts and progress must be inspected frequently and diligently, using the cadence of the five events"],w:["Six months is fine if the plan is detailed","Inspection should happen only when problems appear","Only the Product Owner needs to inspect progress"],why:"Inspection must be frequent and diligent to detect undesirable variances. Scrum's five events give that cadence."},
  {sc:1,type:"single",topic:"Pillars",q:"Every change the team wants to make to how it works must first be approved by a manager two levels up. What happens to adaptation?",a:["It becomes more difficult, because the people involved aren't empowered or self-managing"],w:["It improves, because changes get reviewed","Nothing changes, approval is part of Scrum","It moves to the Sprint Retrospective only"],why:"Adaptation becomes more difficult when the people involved are not empowered or self-managing."},
  {sc:1,type:"single",topic:"Pillars",q:"On day 3 of a Sprint, the Developers learn a service they rely on is being shut down. When should they adapt?",a:["Right away, as soon as they learn it"],w:["At the Sprint Review","At the Sprint Retrospective","In the next Sprint"],why:"A Scrum Team is expected to adapt the moment it learns anything new through inspection."},
  {sc:1,type:"multi",topic:"Values",q:"One team member skips Sprint work to attend unrelated meetings. Another mocks a teammate's ideas. Which two values are most at risk? (Choose two.)",a:["Focus","Respect"],w:["Openness","Courage","Transparency"],why:"Focus is on the work of the Sprint. Respect means seeing each other as capable, independent people."},
  {sc:1,type:"single",topic:"Values",q:"The Sprint Goal is at risk, and a Developer says \"I only do testing, the rest isn't my job.\" Which value is lacking most?",a:["Commitment"],w:["Openness","Courage","Focus"],why:"The Scrum Team commits to achieving its goals and to supporting each other."},
  {sc:1,type:"single",topic:"Values",q:"A manager reviews every small decision the Developers make and doesn't trust them to decide. Which value is not being shown to the team?",a:["Respect"],w:["Focus","Commitment","Openness"],why:"Team members are respected as capable, independent people by the people with whom they work."},
  {sc:1,type:"single",topic:"Values",q:"A stakeholder pushes for a shortcut that would lower quality. The team raises its concern and proposes another option. Which value are they showing?",a:["Courage"],w:["Focus","Commitment","Openness"],why:"Courage: doing the right thing and working on tough problems, even when it's uncomfortable."},
  {sc:1,type:"single",topic:"Values",q:"At the Retrospective, team members openly share mistakes they made during the Sprint. Which value does this show?",a:["Openness"],w:["Focus","Commitment","Courage"],why:"The Scrum Team and its stakeholders are open about the work and the challenges."},
  {sc:1,type:"multi",topic:"Values",q:"A team regularly hides bad news from stakeholders. Which value and which pillar suffer most? (Choose two.)",a:["Openness","Transparency"],w:["Focus","Lean thinking"],why:"Openness is the value about being open on work and challenges. Transparency is the pillar about making the work visible."},
  {sc:1,type:"single",topic:"Values",q:"A new Scrum Master wants the team to \"learn the values\" by reading a values poster in a one-hour session. What does the Scrum Guide say?",a:["Members learn and explore the values as they work with the Scrum events and artifacts"],w:["A one-time training session is enough","The Scrum Master teaches the values before each Sprint","Values are learned by passing a test"],why:"The Scrum Team members learn and explore the values as they work with the Scrum events and artifacts."},
  {sc:1,type:"single",topic:"Values",q:"Trust between a team and its stakeholders is low. According to the Scrum Guide, what builds trust?",a:["Embodying the five values, which brings the pillars to life"],w:["More detailed status reports","Longer Sprints with bigger deliveries","Having managers approve all work"],why:"When the values are embodied, the empirical pillars of transparency, inspection and adaptation come to life, building trust."}
  ]
},
{
  id: "p5-7",
  title: "Pages 5–7",
  sub: "Scrum Team, Developers, Product Owner and Scrum Master",
  qs: [
  // ---- Scrum Team
  {type:"single",topic:"Scrum Team",q:"What is the fundamental unit of Scrum?",a:["A small team of people, the Scrum Team"],w:["The Sprint","The Product Backlog","The Product Owner"],why:"The fundamental unit of Scrum is a small team of people, a Scrum Team."},
  {type:"multi",topic:"Scrum Team",q:"Who makes up a Scrum Team? (Choose three.)",a:["One Scrum Master","One Product Owner","Developers"],w:["A project manager","Key stakeholders","A team lead"],why:"A Scrum Team consists of one Scrum Master, one Product Owner and Developers."},
  {type:"tf",topic:"Scrum Team",q:"True or false: A large Scrum Team may create sub-teams, such as a testing sub-team.",a:["False"],why:"Within a Scrum Team there are no sub-teams or hierarchies."},
  {type:"tf",topic:"Scrum Team",q:"True or false: A Scrum Team can have a team lead who manages the Developers.",a:["False"],why:"There are no hierarchies within a Scrum Team. It is a cohesive unit of professionals."},
  {type:"blank",topic:"Scrum Team",q:"A Scrum Team is a cohesive unit of professionals focused on one objective at a time, the ____.",a:["Product Goal"],w:["Sprint Goal","Definition of Done","release plan"],why:"The team focuses on one objective at a time: the Product Goal."},
  {type:"single",topic:"Scrum Team",q:"What does cross-functional mean in Scrum?",a:["The members have all the skills needed to create value each Sprint"],w:["Each member can do every job on the team","The team includes people from several departments","Members rotate roles every Sprint"],why:"Cross-functional means the members have all the skills necessary to create value each Sprint, as a team."},
  {type:"single",topic:"Scrum Team",q:"What does self-managing mean in Scrum?",a:["The team internally decides who does what, when and how"],w:["The team has no Product Owner","The team decides its own salaries","The team reports to nobody in the organization"],why:"Self-managing means they internally decide who does what, when, and how."},
  {type:"multi",topic:"Scrum Team",q:"A self-managing Scrum Team internally decides which of these? (Choose three.)",a:["Who does the work","When it is done","How it is done"],w:["Which items the Product Owner orders first","The Product Goal"],why:"Self-managing teams decide who does what, when and how. Ordering the Product Backlog and the Product Goal belong to the Product Owner."},
  {type:"single",topic:"Scrum Team",q:"How large is a Scrum Team typically?",a:["10 or fewer people"],w:["3 to 9 Developers plus the PO and SM","Exactly 7 people","As many as the work needs"],why:"Typically 10 or fewer people: small enough to stay nimble, large enough to complete significant work within a Sprint."},
  {type:"multi",topic:"Scrum Team",q:"Why should a Scrum Team stay small? (Choose two.)",a:["Smaller teams communicate better","Smaller teams are more productive"],w:["Smaller teams need no Scrum Master","Smaller teams can skip Sprint Planning"],why:"The guide says smaller teams communicate better and are more productive."},
  {type:"single",topic:"Scrum Team",q:"The Scrum Team should be large enough to:",a:["Complete significant work within a Sprint"],w:["Cover every department","Finish the whole product in one Sprint","Work without a Product Owner"],why:"Small enough to remain nimble, large enough to complete significant work within a Sprint."},
  {type:"single",topic:"Scrum Team",q:"If a Scrum Team becomes too large, what should it consider?",a:["Reorganizing into multiple cohesive Scrum Teams focused on the same product"],w:["Adding a second Product Owner","Splitting into a development team and a testing team","Making the Sprint longer"],why:"Too-large teams should consider reorganizing into multiple cohesive Scrum Teams, each focused on the same product."},
  {type:"multi",topic:"Scrum Team",q:"Several Scrum Teams work on the same product. What must they share? (Choose three.)",a:["The same Product Goal","The same Product Backlog","The same Product Owner"],w:["The same Scrum Master","The same Sprint Backlog"],why:"Teams on one product share the same Product Goal, Product Backlog and Product Owner. Each team has its own Sprint Backlog."},
  {type:"single",topic:"Scrum Team",q:"Which activities is the Scrum Team responsible for?",a:["All product-related activities, from stakeholder collaboration to research and development"],w:["Only writing code","Only testing and release","Only what the Product Owner assigns"],why:"The team is responsible for all product-related activities: stakeholder collaboration, verification, maintenance, operation, experimentation, R&D and anything else required."},
  {type:"multi",topic:"Scrum Team",q:"Which of these are named as Scrum Team responsibilities? (Choose three.)",a:["Stakeholder collaboration","Maintenance and operation","Experimentation"],w:["Setting the company budget","Hiring team members"],why:"The guide lists stakeholder collaboration, verification, maintenance, operation, experimentation, research and development, and anything else that might be required."},
  {type:"single",topic:"Scrum Team",q:"Who structures and empowers the Scrum Team to manage its own work?",a:["The organization"],w:["The Scrum Master","The Product Owner","The stakeholders"],why:"Scrum Teams are structured and empowered by the organization to manage their own work."},
  {type:"single",topic:"Scrum Team",q:"Working in Sprints at a sustainable pace improves the Scrum Team's:",a:["Focus and consistency"],w:["Velocity","Individual performance ratings","Number of releases"],why:"Working in Sprints at a sustainable pace improves the Scrum Team's focus and consistency."},
  {type:"single",topic:"Scrum Team",q:"Who is accountable for creating a valuable, useful Increment every Sprint?",a:["The entire Scrum Team"],w:["The Developers only","The Product Owner only","The Scrum Master"],why:"The entire Scrum Team is accountable for creating a valuable, useful Increment every Sprint."},
  {type:"single",topic:"Scrum Team",q:"How many accountabilities does Scrum define within the Scrum Team?",a:["Three"],w:["Two","Four","Five"],why:"Three: Developers, Product Owner and Scrum Master."},
  {type:"tf",topic:"Scrum Team",q:"True or false: The Scrum Guide calls Developers, Product Owner and Scrum Master \"roles\" with job titles.",a:["False"],why:"The 2020 guide calls them accountabilities, not roles or job titles."},

  // ---- Developers
  {type:"single",topic:"Developers",q:"Who are the Developers in a Scrum Team?",a:["The people committed to creating any aspect of a usable Increment each Sprint"],w:["Only the programmers","Only people with an engineering title","The people who write the Product Backlog"],why:"Developers are committed to creating any aspect of a usable Increment each Sprint. It isn't limited to programmers."},
  {type:"tf",topic:"Developers",q:"True or false: In Scrum, \"Developers\" only means software programmers.",a:["False"],why:"Developers are anyone creating any aspect of the Increment, such as testers, designers, analysts or writers. Skills vary with the domain of work."},
  {type:"single",topic:"Developers",q:"The specific skills needed by the Developers:",a:["Are often broad and vary with the domain of work"],w:["Are defined in the Scrum Guide","Must be the same for every Developer","Are set by the Scrum Master"],why:"The skills are often broad and will vary with the domain of work."},
  {type:"multi",topic:"Developers",q:"Developers are always accountable for which of these? (Choose all that apply.)",a:["Creating a plan for the Sprint, the Sprint Backlog","Instilling quality by adhering to a Definition of Done","Adapting their plan each day toward the Sprint Goal","Holding each other accountable as professionals"],w:["Ordering the Product Backlog","Removing organizational impediments"],why:"These are the four Developer accountabilities. Ordering the backlog is the PO's; removing impediments is the Scrum Master's."},
  {type:"single",topic:"Developers",q:"Who creates the plan for the Sprint (the Sprint Backlog)?",a:["The Developers"],w:["The Product Owner","The Scrum Master","The whole organization"],why:"Developers are accountable for creating a plan for the Sprint, the Sprint Backlog."},
  {type:"blank",topic:"Developers",q:"Developers instill quality by adhering to a ____.",a:["Definition of Done"],w:["Definition of Ready","test plan","Sprint Goal"],why:"Developers instill quality by adhering to a Definition of Done."},
  {type:"blank",topic:"Developers",q:"Developers adapt their plan each day toward the ____.",a:["Sprint Goal"],w:["Product Goal","release date","velocity target"],why:"Developers adapt their plan each day toward the Sprint Goal."},
  {type:"single",topic:"Developers",q:"Who holds Developers accountable as professionals?",a:["Each other"],w:["The Scrum Master","The Product Owner","Their line manager"],why:"Developers hold each other accountable as professionals."},

  // ---- Product Owner
  {type:"single",topic:"Product Owner",q:"The Product Owner is accountable for:",a:["Maximizing the value of the product resulting from the work of the Scrum Team"],w:["Managing the Developers' tasks","Making sure all requested features get built","Writing the Definition of Done"],why:"The PO is accountable for maximizing the value of the product resulting from the work of the Scrum Team."},
  {type:"tf",topic:"Product Owner",q:"True or false: The Scrum Guide prescribes exactly how a Product Owner maximizes value.",a:["False"],why:"How this is done may vary widely across organizations, Scrum Teams and individuals."},
  {type:"multi",topic:"Product Owner",q:"Effective Product Backlog management includes which of these? (Choose all that apply.)",a:["Developing and explicitly communicating the Product Goal","Creating and clearly communicating Product Backlog items","Ordering Product Backlog items","Ensuring the Product Backlog is transparent, visible and understood"],w:["Estimating every Product Backlog item","Assigning items to Developers"],why:"These four are the PO's backlog management duties. Sizing is done by the Developers, and nobody assigns their work."},
  {type:"single",topic:"Product Owner",q:"Who develops and explicitly communicates the Product Goal?",a:["The Product Owner"],w:["The Scrum Master","The Developers","Senior management"],why:"Developing and explicitly communicating the Product Goal is part of the PO's Product Backlog management."},
  {type:"single",topic:"Product Owner",q:"Who is accountable for ordering Product Backlog items?",a:["The Product Owner"],w:["The Developers","The Scrum Master","The stakeholders by vote"],why:"Ordering Product Backlog items is the Product Owner's accountability."},
  {type:"single",topic:"Product Owner",q:"The Product Owner delegates writing Product Backlog items to a Developer. Who is accountable for the Product Backlog now?",a:["The Product Owner"],w:["The Developer who writes them","The Scrum Master","The whole team equally"],why:"The PO may do the work or delegate it, but remains accountable."},
  {type:"blank",topic:"Product Owner",q:"The Product Owner may do the backlog work or delegate it, but the Product Owner remains ____.",a:["accountable"],w:["optional","informed","consulted"],why:"Regardless of delegation, the Product Owner remains accountable."},
  {type:"single",topic:"Product Owner",q:"For Product Owners to succeed, what must the entire organization do?",a:["Respect their decisions"],w:["Approve each of their decisions","Attend every Sprint Review","Give them a manager title"],why:"For Product Owners to succeed, the entire organization must respect their decisions."},
  {type:"multi",topic:"Product Owner",q:"Where are the Product Owner's decisions visible? (Choose two.)",a:["In the content and ordering of the Product Backlog","Through the inspectable Increment at the Sprint Review"],w:["In the Daily Scrum","In the Sprint Retrospective notes"],why:"PO decisions are visible in the content and ordering of the Product Backlog, and through the inspectable Increment at the Sprint Review."},
  {type:"tf",topic:"Product Owner",q:"True or false: A product with many stakeholders can have a committee act as Product Owner.",a:["False"],why:"The Product Owner is one person, not a committee. They may represent the needs of many stakeholders."},
  {type:"single",topic:"Product Owner",q:"How can someone get a change made to the Product Backlog?",a:["By trying to convince the Product Owner"],w:["By asking the Developers directly","By asking the Scrum Master to add it","By escalating to the PO's manager"],why:"Those wanting to change the Product Backlog can do so by trying to convince the Product Owner."},
  {type:"single",topic:"Product Owner",q:"The Product Owner represents the needs of:",a:["Many stakeholders, in the Product Backlog"],w:["Only the customer","Only the Developers","Only senior management"],why:"The PO may represent the needs of many stakeholders in the Product Backlog."},

  // ---- Scrum Master
  {type:"single",topic:"Scrum Master",q:"The Scrum Master is accountable for:",a:["Establishing Scrum as defined in the Scrum Guide, and the Scrum Team's effectiveness"],w:["Delivering the product on time","Assigning tasks to Developers","Maximizing the value of the product"],why:"The SM is accountable for establishing Scrum as defined in the guide and for the Scrum Team's effectiveness."},
  {type:"single",topic:"Scrum Master",q:"How does the Scrum Master establish Scrum?",a:["By helping everyone understand Scrum theory and practice, in the team and the organization"],w:["By enforcing rules and reporting violations","By writing the team's process documents","By approving every change to the process"],why:"They help everyone understand Scrum theory and practice, both within the Scrum Team and the organization."},
  {type:"single",topic:"Scrum Master",q:"How does the Scrum Master make the team more effective?",a:["By enabling the team to improve its practices within the Scrum framework"],w:["By doing the hardest tasks themselves","By setting individual performance targets","By extending the Sprint when needed"],why:"The SM is accountable for the team's effectiveness by enabling it to improve its practices within the Scrum framework."},
  {type:"blank",topic:"Scrum Master",q:"Scrum Masters are true ____ who serve the Scrum Team and the larger organization.",a:["leaders"],w:["managers","coordinators","administrators"],why:"Scrum Masters are true leaders who serve the Scrum Team and the larger organization."},
  {type:"multi",topic:"Scrum Master",q:"How does the Scrum Master serve the Scrum Team? (Choose all that apply.)",a:["Coaching team members in self-management and cross-functionality","Helping the team focus on high-value Increments that meet the Definition of Done","Causing the removal of impediments to the team's progress","Ensuring Scrum events take place and are positive, productive and within the timebox"],w:["Assigning work to Developers","Ordering the Product Backlog"],why:"These four are how the SM serves the team. The SM doesn't assign work or order the backlog."},
  {type:"single",topic:"Scrum Master",q:"The Scrum Master helps the team focus on creating high-value Increments that:",a:["Meet the Definition of Done"],w:["Are released every day","Match the original plan","Use the most story points"],why:"The SM helps the team focus on high-value Increments that meet the Definition of Done."},
  {type:"single",topic:"Scrum Master",q:"Regarding impediments, the Scrum Master is responsible for:",a:["Causing their removal"],w:["Removing every impediment personally","Reporting them to management","Logging them for the Retrospective only"],why:"The SM causes the removal of impediments to the team's progress. They don't have to remove each one themselves."},
  {type:"single",topic:"Scrum Master",q:"The Scrum Master ensures Scrum events are:",a:["Taking place, positive, productive and kept within the timebox"],w:["Run by the Scrum Master personally","Attended by management","Documented in detailed minutes"],why:"The SM ensures all events take place and are positive, productive and kept within the timebox."},
  {type:"multi",topic:"Scrum Master",q:"How does the Scrum Master serve the Product Owner? (Choose all that apply.)",a:["Helping find techniques for effective Product Goal definition and Product Backlog management","Helping the team understand the need for clear and concise Product Backlog items","Helping establish empirical product planning for a complex environment","Facilitating stakeholder collaboration as requested or needed"],w:["Ordering the Product Backlog for the PO","Approving the Product Goal"],why:"These four are how the SM serves the PO. The PO still owns the ordering and the Product Goal."},
  {type:"single",topic:"Scrum Master",q:"Who helps the Scrum Team understand the need for clear and concise Product Backlog items?",a:["The Scrum Master"],w:["The stakeholders","Senior management","The Developers' manager"],why:"Serving the PO, the SM helps the Scrum Team understand the need for clear and concise Product Backlog items."},
  {type:"tf",topic:"Scrum Master",q:"True or false: The Scrum Master facilitates stakeholder collaboration only at the Sprint Review.",a:["False"],why:"The SM facilitates stakeholder collaboration as requested or needed, at any time."},
  {type:"multi",topic:"Scrum Master",q:"How does the Scrum Master serve the organization? (Choose all that apply.)",a:["Leading, training and coaching the organization in its Scrum adoption","Planning and advising Scrum implementations within the organization","Helping employees and stakeholders understand and enact an empirical approach","Removing barriers between stakeholders and Scrum Teams"],w:["Approving budgets for Scrum Teams","Hiring Product Owners"],why:"These four are how the SM serves the organization."},
  {type:"single",topic:"Scrum Master",q:"Which is a Scrum Master service to the organization, not to the Scrum Team?",a:["Removing barriers between stakeholders and Scrum Teams"],w:["Coaching team members in self-management","Causing the removal of impediments to the team's progress","Keeping events within the timebox"],why:"Removing barriers between stakeholders and Scrum Teams is listed under serving the organization."},
  {type:"single",topic:"Accountabilities",q:"Match: who is accountable for maximizing value, who for effectiveness, and who for the Sprint plan?",a:["Product Owner; Scrum Master; Developers"],w:["Scrum Master; Product Owner; Developers","Developers; Scrum Master; Product Owner","Product Owner; Developers; Scrum Master"],why:"PO maximizes value; SM is accountable for the team's effectiveness; Developers create the Sprint Backlog."},

  // ---- Scenarios
  {sc:1,type:"single",topic:"Scrum Team",q:"A manager wants to split a 12-person Scrum Team into a \"build team\" and a \"test team\". What is the best advice?",a:["Avoid sub-teams; consider multiple cross-functional Scrum Teams that share one Product Backlog, Product Goal and Product Owner"],w:["Do it, since specialist sub-teams are more efficient","Keep 12 people but appoint a team lead","Make the Sprints longer so everyone fits"],why:"There are no sub-teams in Scrum. A too-large team should reorganize into multiple cohesive, cross-functional Scrum Teams on the same product."},
  {sc:1,type:"single",topic:"Scrum Team",q:"Mid-Sprint, a senior manager tells two Developers which tasks to do and in what order. What principle is being ignored?",a:["Self-management: the team decides who does what, when and how"],w:["Transparency of the Sprint Backlog","The Product Owner's ordering","The timebox of the Sprint"],why:"Self-managing teams decide internally who does what, when and how."},
  {sc:1,type:"single",topic:"Scrum Team",q:"A team has no one who can do UX design, so every Sprint it waits for a designer from another department. What is missing?",a:["Cross-functionality: the team should have all skills needed to create value each Sprint"],w:["A Scrum Master","A longer Sprint","A Definition of Ready"],why:"Cross-functional teams have all the skills necessary to create value each Sprint. The dependency is an impediment worth fixing."},
  {sc:1,type:"single",topic:"Scrum Team",q:"Three Scrum Teams build one mobile app. Each team wants its own Product Owner and backlog. What does Scrum say?",a:["They share one Product Owner, one Product Backlog and one Product Goal"],w:["Each team should have its own PO and backlog","The Scrum Masters should share one backlog","Only the largest team keeps the backlog"],why:"Multiple Scrum Teams on the same product share the same Product Goal, Product Backlog and Product Owner."},
  {sc:1,type:"single",topic:"Scrum Team",q:"The team keeps working late every night to finish Sprint work, and quality is slipping. What does the Scrum Guide point to?",a:["Working at a sustainable pace improves focus and consistency"],w:["Extend the Sprint to fit the work","Lower the Definition of Done for this Sprint","Add more people mid-Sprint"],why:"Working in Sprints at a sustainable pace improves the Scrum Team's focus and consistency. Quality shouldn't drop."},
  {sc:1,type:"single",topic:"Scrum Team",q:"A Sprint ends without a usable Increment. Leadership asks who is to blame. What is the Scrum answer?",a:["The entire Scrum Team is accountable for creating a valuable, useful Increment every Sprint"],w:["The Developers, because they build it","The Product Owner, because they own value","The Scrum Master, because they own the process"],why:"The entire Scrum Team is accountable for a valuable, useful Increment every Sprint. The team inspects and adapts together."},
  {sc:1,type:"single",topic:"Scrum Team",q:"After release, a production issue appears. A Developer says, \"Operations isn't our job, we only build features.\" What does the guide say?",a:["The Scrum Team is responsible for all product-related activities, including maintenance and operation"],w:["Operations belongs to a separate support team","The Scrum Master should handle it","Only the Product Owner decides who fixes it"],why:"The Scrum Team is responsible for all product-related activities, including verification, maintenance and operation."},
  {sc:1,type:"single",topic:"Developers",q:"The team's tester says, \"I'm not a Developer, so I don't attend the Daily Scrum.\" What is correct?",a:["The tester is a Developer: anyone creating any aspect of the Increment is a Developer"],w:["Testers are stakeholders, not Developers","Testers attend only the Sprint Review","Only programmers attend the Daily Scrum"],why:"Developers are the people committed to creating any aspect of a usable Increment, which includes testing."},
  {sc:1,type:"single",topic:"Developers",q:"The Product Owner writes the task breakdown for the Sprint and gives it to the Developers. What's wrong?",a:["The Developers are accountable for creating the Sprint plan"],w:["Nothing; the PO owns all planning","The Scrum Master should write it instead","The tasks should be approved by stakeholders first"],why:"Creating the plan for the Sprint, the Sprint Backlog, is a Developer accountability."},
  {sc:1,type:"single",topic:"Developers",q:"Near the end of the Sprint, a Developer suggests skipping tests to finish more items. What should happen?",a:["Keep the Definition of Done; quality is instilled by adhering to it"],w:["Skip tests this once and fix later","Ask the Product Owner to approve skipping tests","Move testing to a later \"hardening Sprint\""],why:"Developers instill quality by adhering to a Definition of Done. Undone work is not part of the Increment."},
  {sc:1,type:"single",topic:"Developers",q:"On day 4, the Developers learn their planned approach won't reach the Sprint Goal. What should they do?",a:["Adapt their plan toward the Sprint Goal right away"],w:["Wait for the Retrospective","Change the Sprint Goal without the PO","Continue the original plan as committed"],why:"Developers adapt their plan each day toward the Sprint Goal."},
  {sc:1,type:"single",topic:"Developers",q:"A Developer keeps leaving work unfinished, and the others complain to the Scrum Master to fix it. What does the guide expect first?",a:["Developers hold each other accountable as professionals"],w:["The Scrum Master disciplines the Developer","The Product Owner removes the Developer","The line manager handles it"],why:"Developers are accountable for holding each other accountable as professionals. The SM can coach, but the team owns this."},
  {sc:1,type:"single",topic:"Product Owner",q:"A sales director asks a Developer directly to add a feature this Sprint. What should the Developer do?",a:["Direct the sales director to the Product Owner"],w:["Add it, since sales brings revenue","Ask the Scrum Master to approve it","Add it to the Sprint Backlog and tell the PO later"],why:"Those wanting to change the Product Backlog do so by trying to convince the Product Owner."},
  {sc:1,type:"single",topic:"Product Owner",q:"Marketing, sales and support each want their own person to approve the backlog order. What does Scrum say?",a:["The Product Owner is one person who represents many stakeholders' needs"],w:["Form a committee of all three as Product Owner","Let each department order its own items","Let the Scrum Master break ties"],why:"The PO is one person, not a committee, and may represent the needs of many stakeholders."},
  {sc:1,type:"single",topic:"Product Owner",q:"Leadership overrules the Product Owner's backlog order every week without discussion. What's the main problem?",a:["For the PO to succeed, the organization must respect their decisions"],w:["The PO should work faster","The Developers should order the backlog","There is no problem; leadership has final say"],why:"For Product Owners to succeed, the entire organization must respect their decisions."},
  {sc:1,type:"single",topic:"Product Owner",q:"The Product Owner is overloaded and asks a Business Analyst to write backlog items. A stakeholder says this isn't allowed. Who is right?",a:["The PO may delegate the work but stays accountable"],w:["The stakeholder: only the PO may write items","The BA becomes the new Product Owner","The Scrum Master must approve the delegation"],why:"The PO may do the backlog work or delegate it to others. The PO remains accountable."},
  {sc:1,type:"single",topic:"Product Owner",q:"Stakeholders ask, \"How do we know what the Product Owner decided?\" What is the best answer?",a:["Look at the content and ordering of the Product Backlog and the Increment at the Sprint Review"],w:["Read the PO's weekly status email","Ask the Scrum Master","Wait for the release notes"],why:"PO decisions are visible in the content and ordering of the Product Backlog, and through the inspectable Increment at the Sprint Review."},
  {sc:1,type:"single",topic:"Product Owner",q:"Developers say the backlog items are vague and they don't understand what to build. Which PO responsibility needs attention?",a:["Creating and clearly communicating Product Backlog items, and keeping the backlog transparent and understood"],w:["Ordering the Product Backlog","Developing the Product Goal","Facilitating the Daily Scrum"],why:"The PO creates and clearly communicates backlog items and ensures the backlog is transparent, visible and understood."},
  {sc:1,type:"single",topic:"Product Owner",q:"The team finishes many features, but customers don't use most of them. Which accountability is most at stake?",a:["The Product Owner's accountability for maximizing value"],w:["The Scrum Master's accountability for effectiveness","The Developers' accountability for quality","The stakeholders' accountability for feedback"],why:"The PO is accountable for maximizing the value of the product. Shipping unused features isn't value."},
  {sc:1,type:"single",topic:"Scrum Master",q:"A new Scrum Master starts assigning tasks to Developers each morning. What is wrong?",a:["The team is self-managing; the Scrum Master coaches it rather than assigning work"],w:["Nothing; this is the Scrum Master's job","The Product Owner should assign tasks instead","Tasks should be assigned only at Sprint Planning"],why:"Developers decide who does what. The SM coaches the team in self-management."},
  {sc:1,type:"single",topic:"Scrum Master",q:"The team is blocked for days waiting for test environment access from another department. What should the Scrum Master do?",a:["Cause the removal of the impediment, for example by working with that department"],w:["Tell the team to wait patiently","Add the issue to the Retrospective agenda only","Ask the Product Owner to cancel the Sprint"],why:"The SM causes the removal of impediments to the team's progress."},
  {sc:1,type:"single",topic:"Scrum Master",q:"Daily Scrums often run 40 minutes and turn into problem-solving sessions. What should the Scrum Master do?",a:["Ensure events are productive and kept within the timebox"],w:["Cancel the Daily Scrum","Run the meeting and assign actions","Let it run as long as needed"],why:"The SM ensures all Scrum events take place and are positive, productive and kept within the timebox."},
  {sc:1,type:"single",topic:"Scrum Master",q:"The Product Owner struggles to write a clear Product Goal. How can the Scrum Master help?",a:["Help the PO find techniques for effective Product Goal definition"],w:["Write the Product Goal for the PO","Let the Developers decide the Product Goal","Skip the Product Goal until later"],why:"The SM serves the PO by helping find techniques for effective Product Goal definition and backlog management."},
  {sc:1,type:"single",topic:"Scrum Master",q:"Stakeholders rarely talk to the team, and the PO wants their input. What can the Scrum Master do?",a:["Facilitate stakeholder collaboration as requested or needed"],w:["Collect stakeholder requests and order the backlog","Tell stakeholders to wait for the release","Report the team's progress to stakeholders weekly"],why:"The SM serves the PO by facilitating stakeholder collaboration as requested or needed."},
  {sc:1,type:"single",topic:"Scrum Master",q:"Leadership wants a fixed 12-month plan for a complex product with many unknowns. How can the Scrum Master help?",a:["Help establish empirical product planning, and help stakeholders understand an empirical approach"],w:["Build the 12-month plan for them","Tell leadership Scrum doesn't plan","Ask the Developers to estimate everything upfront"],why:"The SM helps establish empirical product planning for a complex environment and helps the organization enact an empirical approach."},
  {sc:1,type:"single",topic:"Scrum Master",q:"Other departments keep misunderstanding how Scrum works and ask for weekly status reports. Which Scrum Master service fits best?",a:["Leading, training and coaching the organization in its Scrum adoption"],w:["Coaching the Developers in self-management","Ordering the Product Backlog","Ensuring the Daily Scrum is timeboxed"],why:"Serving the organization includes leading, training and coaching it in its Scrum adoption."},
  {sc:1,type:"multi",topic:"Accountabilities",q:"In a Sprint Review, a stakeholder demands a new feature be added to the current Sprint. Who decides, and how? (Choose two.)",a:["The Product Owner decides whether and where it goes in the Product Backlog","The Developers decide what they can take on without endangering the Sprint Goal"],w:["The stakeholder decides, since they requested it","The Scrum Master decides as the process owner"],why:"The PO orders the Product Backlog; the Developers own the Sprint Backlog and the plan toward the Sprint Goal."},
  {sc:1,type:"single",topic:"Accountabilities",q:"A company wants to hire a Scrum Master who will also act as the team's project manager and report individual performance. What is the concern?",a:["The Scrum Master is a servant leader who coaches self-management, not a manager who controls or rates the team"],w:["No concern; this is a typical Scrum Master job","The Product Owner should do the reporting","The Scrum Master should report only team velocity"],why:"Scrum Masters are true leaders who serve. Controlling work and rating individuals undermines self-management."}
  ]
},
{
  id: "events",
  title: "Scrum Events",
  sub: "The Sprint, Sprint Planning, Daily Scrum, Sprint Review and Retrospective",
  qs: [
  // ---- Events in general
  {type:"single",topic:"Events",q:"What is the Sprint in relation to the other Scrum events?",a:["A container for all other events"],w:["The first event, followed by the others","An optional event for long projects","The same as Sprint Planning"],why:"The Sprint is a container for all other events."},
  {type:"single",topic:"Events",q:"Each event in Scrum is a formal opportunity to:",a:["Inspect and adapt Scrum artifacts"],w:["Report status to management","Assign work to team members","Approve the Increment"],why:"Each event is a formal opportunity to inspect and adapt Scrum artifacts."},
  {type:"single",topic:"Events",q:"What happens if events are not operated as prescribed?",a:["Opportunities to inspect and adapt are lost"],w:["The Sprint is automatically cancelled","The Scrum Master must report it","Nothing, events are optional"],why:"Failure to operate any events as prescribed results in lost opportunities to inspect and adapt."},
  {type:"multi",topic:"Events",q:"Why are events used in Scrum? (Choose two.)",a:["To create regularity","To minimize the need for meetings not defined in Scrum"],w:["To track individual performance","To give management status updates"],why:"Events create regularity and minimize the need for meetings not defined in Scrum."},
  {type:"single",topic:"Events",q:"Optimally, all events are held at the same time and place. Why?",a:["To reduce complexity"],w:["To make reporting easier","Because the Scrum Guide requires one room","To save meeting-room costs"],why:"Optimally, all events are held at the same time and place to reduce complexity."},
  {type:"blank",topic:"Events",q:"Scrum events are specifically designed to enable the ____ required.",a:["transparency"],w:["documentation","approval","velocity"],why:"These events are specifically designed to enable the transparency required."},
  {type:"order",topic:"Events",q:"Put the events inside a Sprint in the order they happen.",items:["Sprint Planning","Daily Scrums","Sprint Review","Sprint Retrospective"],why:"Planning starts the Sprint, Daily Scrums run every working day, the Review is second to last, and the Retrospective concludes the Sprint."},

  // ---- The Sprint
  {type:"blank",topic:"Sprint",q:"Sprints are the ____ of Scrum, where ideas are turned into value.",a:["heartbeat"],w:["engine","backbone","foundation"],why:"Sprints are the heartbeat of Scrum, where ideas are turned into value."},
  {type:"single",topic:"Sprint",q:"Why are Sprints fixed-length events of one month or less?",a:["To create consistency"],w:["To match payroll cycles","So every release is monthly","To limit the number of meetings"],why:"They are fixed-length events of one month or less to create consistency."},
  {type:"single",topic:"Sprint",q:"When does a new Sprint start?",a:["Immediately after the previous Sprint concludes"],w:["After a short planning break","When the Product Owner approves it","At the start of the next calendar month"],why:"A new Sprint starts immediately after the conclusion of the previous Sprint."},
  {type:"tf",topic:"Sprint",q:"True or false: A team may take a few days between Sprints to fix bugs and plan.",a:["False"],why:"A new Sprint starts immediately after the previous one. There are no gaps or in-between phases."},
  {type:"single",topic:"Sprint",q:"Where does all the work necessary to achieve the Product Goal happen?",a:["Within Sprints"],w:["Partly in Sprints and partly in release phases","In a Sprint 0 before regular Sprints","Outside Sprints, during refinement weeks"],why:"All the work necessary to achieve the Product Goal, including all events, happens within Sprints."},
  {type:"multi",topic:"Sprint",q:"Which of these are true during the Sprint? (Choose all that apply.)",a:["No changes are made that would endanger the Sprint Goal","Quality does not decrease","The Product Backlog is refined as needed","Scope may be clarified and renegotiated with the Product Owner"],w:["The Sprint Backlog is frozen","The Sprint length can be extended if needed"],why:"These four rules hold during the Sprint. The Sprint Backlog keeps changing as the plan adapts, and the length is fixed."},
  {type:"single",topic:"Sprint",q:"As more is learned during a Sprint, scope may be clarified and renegotiated with:",a:["The Product Owner"],w:["The Scrum Master","Key stakeholders","The Developers' manager"],why:"Scope may be clarified and renegotiated with the Product Owner as more is learned."},
  {type:"single",topic:"Sprint",q:"How do Sprints enable predictability?",a:["By ensuring inspection and adaptation of progress toward a Product Goal at least every calendar month"],w:["By fixing scope at the start of the project","By measuring velocity each Sprint","By releasing every Sprint"],why:"Sprints enable predictability by ensuring inspection and adaptation of progress toward a Product Goal at least every calendar month."},
  {type:"multi",topic:"Sprint",q:"What can happen when a Sprint's horizon is too long? (Choose three.)",a:["The Sprint Goal may become invalid","Complexity may rise","Risk may increase"],w:["The team becomes more predictable","Stakeholders get more feedback"],why:"When a Sprint's horizon is too long the Sprint Goal may become invalid, complexity may rise, and risk may increase."},
  {type:"multi",topic:"Sprint",q:"Why might a team use shorter Sprints? (Choose two.)",a:["To generate more learning cycles","To limit the risk of cost and effort to a smaller time frame"],w:["To avoid the Sprint Retrospective","To reduce the Definition of Done"],why:"Shorter Sprints generate more learning cycles and limit risk of cost and effort to a smaller time frame."},
  {type:"single",topic:"Sprint",q:"How does the Scrum Guide say each Sprint may be considered?",a:["A short project"],w:["A phase of a larger project","A milestone","A release"],why:"Each Sprint may be considered a short project."},
  {type:"tf",topic:"Sprint",q:"True or false: Burn-downs, burn-ups and cumulative flows replace the importance of empiricism.",a:["False"],why:"These forecasting practices can be useful but do not replace the importance of empiricism."},
  {type:"single",topic:"Sprint",q:"In complex environments, what may be used for forward-looking decision making?",a:["Only what has already happened"],w:["Burn-down forecasts","Expert estimates","The original project plan"],why:"In complex environments, what will happen is unknown. Only what has already happened may be used for forward-looking decision making."},
  {type:"single",topic:"Sprint",q:"Which forecasting practices does the Scrum Guide mention as proven useful?",a:["Burn-downs, burn-ups and cumulative flows"],w:["Story points and velocity","Gantt charts and critical path","Earned value analysis"],why:"The guide names burn-downs, burn-ups and cumulative flows, while stressing they don't replace empiricism."},
  {type:"single",topic:"Sprint",q:"When could a Sprint be cancelled?",a:["When the Sprint Goal becomes obsolete"],w:["When the team falls behind","When a stakeholder requests it","When a team member leaves"],why:"A Sprint could be cancelled if the Sprint Goal becomes obsolete."},
  {type:"single",topic:"Sprint",q:"Who has the authority to cancel a Sprint?",a:["Only the Product Owner"],w:["The Scrum Master","The Developers","Senior management"],why:"Only the Product Owner has the authority to cancel the Sprint."},

  // ---- Sprint Planning
  {type:"single",topic:"Sprint Planning",q:"What does Sprint Planning do?",a:["Initiates the Sprint by laying out the work to be performed"],w:["Reviews the previous Sprint's results","Sets the release date","Assigns tasks to each Developer"],why:"Sprint Planning initiates the Sprint by laying out the work to be performed for the Sprint."},
  {type:"single",topic:"Sprint Planning",q:"Who creates the Sprint Planning plan?",a:["The entire Scrum Team, collaboratively"],w:["The Product Owner","The Scrum Master","The Developers alone"],why:"The resulting plan is created by the collaborative work of the entire Scrum Team."},
  {type:"single",topic:"Sprint Planning",q:"What does the Product Owner make sure of before Sprint Planning?",a:["Attendees are prepared to discuss the most important backlog items and how they map to the Product Goal"],w:["Every backlog item is estimated","The Sprint Backlog is already written","Stakeholders have approved the plan"],why:"The PO ensures attendees are prepared to discuss the most important Product Backlog items and how they map to the Product Goal."},
  {type:"tf",topic:"Sprint Planning",q:"True or false: The Scrum Team may invite other people to Sprint Planning to provide advice.",a:["True"],why:"The Scrum Team may also invite other people to attend Sprint Planning to provide advice."},
  {type:"order",topic:"Sprint Planning",q:"Put Sprint Planning's three topics in order.",items:["Why is this Sprint valuable?","What can be Done this Sprint?","How will the chosen work get done?"],why:"Topic One is why, Topic Two is what, Topic Three is how."},
  {type:"single",topic:"Sprint Planning",q:"In Topic One (Why), who proposes how the product could increase its value and utility in the Sprint?",a:["The Product Owner"],w:["The Developers","The Scrum Master","Key stakeholders"],why:"The Product Owner proposes how the product could increase its value and utility in the current Sprint."},
  {type:"single",topic:"Sprint Planning",q:"Who defines the Sprint Goal?",a:["The whole Scrum Team, collaborating"],w:["The Product Owner alone","The Developers alone","The Scrum Master"],why:"The whole Scrum Team collaborates to define a Sprint Goal."},
  {type:"single",topic:"Sprint Planning",q:"The Sprint Goal communicates:",a:["Why the Sprint is valuable to stakeholders"],w:["Which tasks each Developer will do","How many story points will be done","The release date"],why:"The Sprint Goal communicates why the Sprint is valuable to stakeholders."},
  {type:"single",topic:"Sprint Planning",q:"When must the Sprint Goal be finalized?",a:["Before the end of Sprint Planning"],w:["By the first Daily Scrum","Before the Sprint Review","Any time during the Sprint"],why:"The Sprint Goal must be finalized prior to the end of Sprint Planning."},
  {type:"single",topic:"Sprint Planning",q:"In Topic Two (What), who selects items from the Product Backlog for the Sprint?",a:["The Developers, through discussion with the Product Owner"],w:["The Product Owner alone","The Scrum Master","Stakeholders, by vote"],why:"Through discussion with the PO, the Developers select items from the Product Backlog."},
  {type:"single",topic:"Sprint Planning",q:"Refining items during Sprint Planning increases:",a:["Understanding and confidence"],w:["Velocity","Scope","The Sprint length"],why:"The Scrum Team may refine these items during this process, which increases understanding and confidence."},
  {type:"multi",topic:"Sprint Planning",q:"What helps Developers feel more confident in their Sprint forecast? (Choose three.)",a:["Their past performance","Their upcoming capacity","Their Definition of Done"],w:["The Product Owner's deadline","Management's targets"],why:"The more Developers know about their past performance, upcoming capacity and Definition of Done, the more confident their forecasts."},
  {type:"single",topic:"Sprint Planning",q:"In Topic Three (How), how is work often planned?",a:["By decomposing backlog items into smaller work items of one day or less"],w:["By assigning each item to one Developer","By estimating each item in hours","By writing detailed specifications"],why:"This is often done by decomposing Product Backlog items into smaller work items of one day or less."},
  {type:"single",topic:"Sprint Planning",q:"Who decides how to turn Product Backlog items into Increments of value?",a:["Only the Developers"],w:["The Product Owner","The Scrum Master","The Developers with management approval"],why:"How this is done is at the sole discretion of the Developers. No one else tells them how."},
  {type:"multi",topic:"Sprint Planning",q:"Which three things together make up the Sprint Backlog? (Choose three.)",a:["The Sprint Goal","The Product Backlog items selected for the Sprint","The plan for delivering them"],w:["The Definition of Done","The Product Goal"],why:"The Sprint Goal, the selected items and the plan for delivering them are together the Sprint Backlog."},
  {type:"single",topic:"Sprint Planning",q:"What is the maximum timebox for Sprint Planning in a one-month Sprint?",a:["8 hours"],w:["4 hours","2 hours","1 day per week of Sprint"],why:"Sprint Planning is timeboxed to a maximum of eight hours for a one-month Sprint."},

  // ---- Daily Scrum
  {type:"single",topic:"Daily Scrum",q:"What is the purpose of the Daily Scrum?",a:["Inspect progress toward the Sprint Goal and adapt the Sprint Backlog as necessary"],w:["Give a status update to the Scrum Master","Report hours worked","Review the Increment with stakeholders"],why:"The Daily Scrum inspects progress toward the Sprint Goal and adapts the Sprint Backlog, adjusting upcoming planned work."},
  {type:"single",topic:"Daily Scrum",q:"Who is the Daily Scrum for?",a:["The Developers"],w:["The whole Scrum Team and stakeholders","The Scrum Master","The Product Owner"],why:"The Daily Scrum is a 15-minute event for the Developers of the Scrum Team."},
  {type:"single",topic:"Daily Scrum",q:"How long is the Daily Scrum?",a:["15 minutes"],w:["15 minutes per Developer","30 minutes","As long as needed"],why:"The Daily Scrum is a 15-minute event, whatever the Sprint length."},
  {type:"single",topic:"Daily Scrum",q:"When do the Product Owner or Scrum Master take part in the Daily Scrum as Developers?",a:["When they are actively working on items in the Sprint Backlog"],w:["Always","Never","Only when invited by management"],why:"If the PO or SM are actively working on Sprint Backlog items, they participate as Developers."},
  {type:"single",topic:"Daily Scrum",q:"Why is the Daily Scrum held at the same time and place every working day?",a:["To reduce complexity"],w:["So managers can attend","To track attendance","Because it must be in person"],why:"To reduce complexity, it is held at the same time and place every working day of the Sprint."},
  {type:"tf",topic:"Daily Scrum",q:"True or false: The Daily Scrum must follow the three questions: what I did yesterday, what I'll do today, and my blockers.",a:["False"],why:"Developers can select whatever structure and techniques they want, as long as it focuses on progress toward the Sprint Goal and produces an actionable plan."},
  {type:"multi",topic:"Daily Scrum",q:"Whatever structure they choose, what must the Daily Scrum do? (Choose two.)",a:["Focus on progress toward the Sprint Goal","Produce an actionable plan for the next day of work"],w:["Cover every Developer's task list","Be facilitated by the Scrum Master"],why:"It must focus on progress toward the Sprint Goal and produce an actionable plan for the next day of work."},
  {type:"multi",topic:"Daily Scrum",q:"What do Daily Scrums improve or achieve? (Choose all that apply.)",a:["Improve communications","Identify impediments","Promote quick decision-making","Eliminate the need for other meetings"],w:["Replace the Sprint Review","Measure individual productivity"],why:"Daily Scrums improve communications, identify impediments, promote quick decision-making and eliminate the need for other meetings."},
  {type:"tf",topic:"Daily Scrum",q:"True or false: The Daily Scrum is the only time Developers may adjust their plan.",a:["False"],why:"Developers often meet throughout the day for more detailed discussions about adapting or re-planning the rest of the Sprint's work."},
  {type:"blank",topic:"Daily Scrum",q:"The Daily Scrum creates focus and improves ____.",a:["self-management"],w:["velocity","reporting","predictability"],why:"Choosing their own structure, focused on the Sprint Goal, creates focus and improves self-management."},

  // ---- Sprint Review
  {type:"single",topic:"Sprint Review",q:"What is the purpose of the Sprint Review?",a:["Inspect the outcome of the Sprint and determine future adaptations"],w:["Approve the Increment for release","Demonstrate features to the Product Owner","Improve the team's way of working"],why:"The Sprint Review inspects the outcome of the Sprint and determines future adaptations."},
  {type:"single",topic:"Sprint Review",q:"Who does the Scrum Team present its results to at the Sprint Review?",a:["Key stakeholders"],w:["The Scrum Master","Senior management only","The Product Owner only"],why:"The Scrum Team presents the results of their work to key stakeholders, and progress toward the Product Goal is discussed."},
  {type:"multi",topic:"Sprint Review",q:"What do the Scrum Team and stakeholders review at the Sprint Review? (Choose two.)",a:["What was accomplished in the Sprint","What has changed in their environment"],w:["Each Developer's performance","How the team can work better together"],why:"They review what was accomplished and what has changed in their environment, then collaborate on what to do next. Team improvement is the Retrospective."},
  {type:"single",topic:"Sprint Review",q:"What may be adjusted during the Sprint Review to meet new opportunities?",a:["The Product Backlog"],w:["The Sprint Backlog of the finished Sprint","The Definition of Done","The Sprint length"],why:"The Product Backlog may also be adjusted to meet new opportunities."},
  {type:"tf",topic:"Sprint Review",q:"True or false: The Sprint Review is mainly a presentation or demo for stakeholders.",a:["False"],why:"The Sprint Review is a working session, and the Scrum Team should avoid limiting it to a presentation."},
  {type:"single",topic:"Sprint Review",q:"Where does the Sprint Review sit in the Sprint?",a:["It is the second-to-last event"],w:["It is the last event","It happens mid-Sprint","It happens after the Retrospective"],why:"The Sprint Review is the second-to-last event of the Sprint; the Retrospective comes last."},
  {type:"single",topic:"Sprint Review",q:"What is the maximum timebox for the Sprint Review in a one-month Sprint?",a:["4 hours"],w:["8 hours","3 hours","2 hours"],why:"The Sprint Review is timeboxed to a maximum of four hours for a one-month Sprint."},

  // ---- Retrospective
  {type:"single",topic:"Retrospective",q:"What is the purpose of the Sprint Retrospective?",a:["Plan ways to increase quality and effectiveness"],w:["Inspect the Increment with stakeholders","Plan the next Sprint's work","Report problems to management"],why:"The purpose of the Sprint Retrospective is to plan ways to increase quality and effectiveness."},
  {type:"multi",topic:"Retrospective",q:"What does the Scrum Team inspect at the Retrospective? (Choose all that apply.)",a:["Individuals","Interactions","Processes","Tools","Their Definition of Done"],w:["The Product Goal","Stakeholder satisfaction scores"],why:"The team inspects individuals, interactions, processes, tools and their Definition of Done."},
  {type:"single",topic:"Retrospective",q:"At the Retrospective, what happens to assumptions that led the team astray?",a:["They are identified and their origins explored"],w:["They are reported to management","They are ignored once fixed","The Scrum Master records them for audit"],why:"Assumptions that led them astray are identified and their origins explored."},
  {type:"single",topic:"Retrospective",q:"When are the most impactful improvements addressed?",a:["As soon as possible; they may be added to the next Sprint Backlog"],w:["At the next release","Only after management approval","At the next Retrospective"],why:"The most impactful improvements are addressed as soon as possible and may even be added to the Sprint Backlog for the next Sprint."},
  {type:"single",topic:"Retrospective",q:"Which event concludes the Sprint?",a:["The Sprint Retrospective"],w:["The Sprint Review","The final Daily Scrum","The release"],why:"The Sprint Retrospective concludes the Sprint."},
  {type:"single",topic:"Retrospective",q:"What is the maximum timebox for the Retrospective in a one-month Sprint?",a:["3 hours"],w:["4 hours","1 hour","8 hours"],why:"The Retrospective is timeboxed to a maximum of three hours for a one-month Sprint."},
  {type:"single",topic:"Timeboxes",q:"For a one-month Sprint, match the maximum timeboxes: Planning, Review, Retrospective.",a:["8 hours, 4 hours, 3 hours"],w:["4 hours, 8 hours, 3 hours","8 hours, 3 hours, 4 hours","4 hours, 4 hours, 2 hours"],why:"Planning 8 h, Review 4 h, Retrospective 3 h. Shorter Sprints usually have shorter events; the Daily Scrum stays 15 minutes."},
  {type:"tf",topic:"Timeboxes",q:"True or false: For a two-week Sprint, Sprint Planning must still take 8 hours.",a:["False"],why:"8 hours is the maximum for a one-month Sprint. For shorter Sprints, the event is usually shorter."},

  // ---- Scenarios (Promita's Black Friday Visibility Checker team)
  {sc:1,type:"single",topic:"Sprint",q:"Promita (PO) runs one-week Sprints for a Black Friday checker. The Developers want a 2-day gap between Sprints to tidy up code. What does Scrum say?",a:["A new Sprint starts immediately after the previous one; tidy-up work goes inside a Sprint"],w:["Allow the gap, since it's technical work","Add a Sprint 0 for cleanup","Let the Scrum Master decide"],why:"A new Sprint starts immediately after the previous one. All work happens within Sprints."},
  {sc:1,type:"single",topic:"Sprint",q:"Mid-Sprint, a merchant asks Promita's team to add a pricing report. It would take the team away from the Sprint Goal \"teammates can check a pasted list.\" What should happen?",a:["Promita adds it to the Product Backlog; nothing that endangers the Sprint Goal goes into this Sprint"],w:["Add it to the Sprint because merchants are key stakeholders","Extend the Sprint to fit both","Cancel the Sprint and start a new one"],why:"During the Sprint, no changes are made that would endanger the Sprint Goal."},
  {sc:1,type:"single",topic:"Sprint",q:"To hit the Black Friday date, a Developer suggests skipping the 50-item accuracy check in the Definition of Done. What does Scrum say?",a:["Quality does not decrease during the Sprint; keep the Definition of Done"],w:["Skip it this once because of the deadline","Ask the PO to approve the shortcut","Do the check after Black Friday"],why:"During the Sprint, quality does not decrease."},
  {sc:1,type:"single",topic:"Sprint",q:"Halfway through a Sprint, the Developers learn that the fix-list export is harder than planned. What can they do?",a:["Clarify and renegotiate scope with Promita, keeping the Sprint Goal"],w:["Drop the Sprint Goal","Extend the Sprint by a week","Lower the quality bar"],why:"Scope may be clarified and renegotiated with the Product Owner as more is learned."},
  {sc:1,type:"single",topic:"Sprint",q:"Walmart cancels the Black Friday event online, so the checker's Sprint Goal no longer makes sense. Who can cancel the Sprint?",a:["Only Promita, the Product Owner"],w:["Her manager","The Scrum Master","The Developers"],why:"A Sprint could be cancelled if the Sprint Goal becomes obsolete. Only the Product Owner has that authority."},
  {sc:1,type:"single",topic:"Sprint",q:"Promita's manager asks her to cancel the Sprint because one Developer is on sick leave. Is that a valid reason?",a:["No; a Sprint is cancelled only if the Sprint Goal becomes obsolete"],w:["Yes, any loss of capacity is a reason","Yes, if the Scrum Master agrees","Yes, if the manager insists"],why:"Losing capacity doesn't make the goal obsolete. The team adapts its plan and renegotiates scope with the PO."},
  {sc:1,type:"single",topic:"Sprint",q:"With Black Friday only weeks away, why did Promita choose one-week Sprints instead of one-month Sprints?",a:["Shorter Sprints give more learning cycles and limit risk to a smaller time frame"],w:["One-month Sprints aren't allowed","Shorter Sprints remove the need for a Retrospective","Shorter Sprints mean less planning is required"],why:"Shorter Sprints generate more learning cycles and limit risk of cost and effort to a smaller time frame."},
  {sc:1,type:"single",topic:"Sprint",q:"Promita's manager wants a burn-down chart to promise the exact delivery date of every feature. What is the Scrum view?",a:["Forecasts can help, but in complex work only what has already happened can guide decisions"],w:["Burn-downs guarantee delivery dates","Burn-downs are not allowed in Scrum","The Scrum Master should commit to the dates"],why:"Burn-downs, burn-ups and cumulative flows are useful but do not replace empiricism."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"At Sprint Planning, Promita arrives without having looked at the backlog, so the team spends the time guessing what matters. Which responsibility did she miss?",a:["Making sure attendees are prepared to discuss the most important items and how they map to the Product Goal"],w:["Writing the Sprint plan","Assigning tasks","Setting the timebox"],why:"The PO ensures attendees are prepared to discuss the most important Product Backlog items and how they map to the Product Goal."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"Promita's team isn't sure what export columns are available. Can they invite someone from the data team to Sprint Planning?",a:["Yes, the Scrum Team may invite other people to provide advice"],w:["No, only the Scrum Team may attend","Only if the Scrum Master runs the event","Only to the Sprint Review"],why:"The Scrum Team may invite other people to attend Sprint Planning to provide advice."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"Promita writes the Sprint Goal alone before Sprint Planning and announces it. What does the guide say?",a:["She proposes how to increase value, but the whole Scrum Team defines the Sprint Goal"],w:["That's correct; the PO owns the Sprint Goal","The Developers alone write the Sprint Goal","The Scrum Master writes the Sprint Goal"],why:"The PO proposes; the whole Scrum Team collaborates to define the Sprint Goal."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"Promita tells the Developers to take all 8 backlog items into a one-week Sprint. What does Scrum say about selecting work?",a:["The Developers select items through discussion with the PO, based on capacity and past performance"],w:["The PO decides how much the team takes","The Scrum Master sets the amount","Take all items and extend the Sprint if needed"],why:"Through discussion with the PO, the Developers select the items. Their past performance, capacity and DoD shape the forecast."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"Promita starts telling the Developers which JavaScript approach to use for the CSV export. What is the issue?",a:["How the work gets done is at the sole discretion of the Developers"],w:["None; the PO decides the technical approach","Only the Scrum Master may suggest approaches","The approach must be approved by stakeholders"],why:"No one else tells the Developers how to turn Product Backlog items into Increments of value."},
  {sc:1,type:"single",topic:"Sprint Planning",q:"Sprint Planning for a one-week Sprint has run 6 hours with no end in sight. What should happen?",a:["Keep it within the timebox; for shorter Sprints, Planning is usually shorter than 8 hours"],w:["Continue until every task is estimated","Extend the Sprint by a day","Let the PO finish planning alone"],why:"8 hours is the maximum for a one-month Sprint; for shorter Sprints the event is usually shorter."},
  {sc:1,type:"single",topic:"Daily Scrum",q:"Promita's Daily Scrum has become a 15-minute status report where each person tells her what they did. What's wrong?",a:["It's for the Developers to inspect progress toward the Sprint Goal and plan the next day, not to report to the PO"],w:["Nothing; status reports are the purpose","It should be 30 minutes","The Scrum Master should take the reports instead"],why:"The Daily Scrum is for the Developers to inspect progress toward the Sprint Goal and adapt the Sprint Backlog."},
  {sc:1,type:"single",topic:"Daily Scrum",q:"Promita is writing the how-to page in Confluence, which is a Sprint Backlog item. Should she attend the Daily Scrum?",a:["Yes, she participates as a Developer while working on Sprint Backlog items"],w:["No, the PO never attends","Only if the Scrum Master invites her","Only to answer questions"],why:"If the PO or SM are actively working on Sprint Backlog items, they participate as Developers."},
  {sc:1,type:"single",topic:"Daily Scrum",q:"At the Daily Scrum, a Developer finds the export has no department column. The discussion to fix it would take 40 minutes. What should happen?",a:["Note the impediment and plan; the people needed meet right after to work it out"],w:["Extend the Daily Scrum to 40 minutes","Wait for the Retrospective","Cancel the Daily Scrum tomorrow"],why:"The Daily Scrum stays 15 minutes. Developers often meet throughout the day for detailed discussions and re-planning."},
  {sc:1,type:"single",topic:"Daily Scrum",q:"Promita's team is fully remote and wants to skip the Daily Scrum on busy days and chat on Teams instead. What is the risk?",a:["They lose a regular chance to inspect progress toward the Sprint Goal and adapt"],w:["None; the Daily Scrum is optional","Only the Scrum Master is affected","The Sprint becomes invalid"],why:"Skipping events loses opportunities to inspect and adapt. The Daily Scrum can be held online at the same time each day."},
  {sc:1,type:"single",topic:"Sprint Review",q:"At the Sprint Review, Promita plans a 20-minute slide deck and no hands-on time with the checker. What's the problem?",a:["The Sprint Review is a working session; stakeholders should try the Increment and discuss next steps"],w:["Slides are required for the Review","The Review should be with the PO only","There is no problem"],why:"The Sprint Review is a working session, and the Scrum Team should avoid limiting it to a presentation."},
  {sc:1,type:"single",topic:"Sprint Review",q:"At the Sprint Review, a category manager says Optical is now in scope for Black Friday. What should Promita do?",a:["Adjust the Product Backlog to reflect the change"],w:["Change the finished Sprint's goal","Ignore it until after Black Friday","Ask the Scrum Master to decide"],why:"The team reviews what has changed in the environment, and the Product Backlog may be adjusted to meet new opportunities."},
  {sc:1,type:"single",topic:"Sprint Review",q:"Promita invites only her own team to the Sprint Review. Who is missing?",a:["Key stakeholders, such as her managers and the teammates who will use the checker"],w:["No one; the Review is for the Scrum Team","The Scrum Master","The vendor agency"],why:"The Scrum Team presents the results of their work to key stakeholders, and progress toward the Product Goal is discussed."},
  {sc:1,type:"single",topic:"Sprint Review",q:"Promita's team wants to hold the Retrospective first and the Sprint Review last. What does the guide say?",a:["The Sprint Review is second to last; the Retrospective concludes the Sprint"],w:["The order doesn't matter","The Review always comes first in the Sprint","They can be combined into one meeting"],why:"The Sprint Review is the second-to-last event; the Retrospective concludes the Sprint."},
  {sc:1,type:"single",topic:"Retrospective",q:"At the Retrospective, the team realizes they assumed the export always padded GTINs to 14 digits, and it didn't. What should they do with this?",a:["Identify the assumption, explore where it came from, and plan an improvement"],w:["Blame whoever wrote that code","Ignore it because it's fixed","Report it to management"],why:"Assumptions that led them astray are identified and their origins explored."},
  {sc:1,type:"single",topic:"Retrospective",q:"The team agrees code reviews are taking too long and slowing the Sprint. When should they act on this improvement?",a:["As soon as possible; they can add it to the next Sprint Backlog"],w:["After Black Friday","Only when the manager approves","At the next Retrospective"],why:"The most impactful improvements are addressed as soon as possible and may be added to the next Sprint Backlog."},
  {sc:1,type:"single",topic:"Retrospective",q:"At the Retrospective, the team wants to add \"tested on real event lists\" to the Definition of Done. Is that in scope?",a:["Yes, the Definition of Done is one of the things inspected at the Retrospective"],w:["No, only the PO can change the DoD","No, the DoD is fixed for the product's life","Only at the Sprint Review"],why:"The Scrum Team inspects individuals, interactions, processes, tools and their Definition of Done."},
  {sc:1,type:"single",topic:"Retrospective",q:"Promita's manager asks the team to discuss new features for the checker at the Retrospective. Which event is that better suited to?",a:["The Sprint Review or ongoing backlog refinement"],w:["The Retrospective","The Daily Scrum","Sprint Planning's Topic Three"],why:"The Retrospective is about quality and effectiveness of how the team works. Product direction is discussed at the Sprint Review and in refinement."}
  ]
}
];
